  'from pathlib import Path\n'
  '\n'
  'from .files import fingerprint\n'
  'from .model import Item, Plan\n'
  '\n'
  'DJI = re.compile(r"^DJI_(\\d{8})(\\d{6})_.+\\.(jpg|jpeg|mp4|wav|lrf)$", re.I)\n'
