  '    else:\n'
  '        root = ET.Element("{" + NS["x"] + "}xmpmeta")\n'
  '        ET.SubElement(root, "{" + NS["rdf"] + "}RDF")\n'
  '    set_property(root, "tiff", "Make", expected["make"])\n'
  '    set_property(root, "tiff", "Model", expected["model"])\n'
  '    if "lensModel" in expected:\n'
  '        # aux:LensID expects a numeric identifier. Writing a lens name there\n'
  '        # creates Composite:LensID = "Unknown (...)" in ExifTool, which masks\n'
  '        # LensModel in Immich. Use the standard textual property instead.\n'
  '        set_property(root, "exifEX", "LensModel", expected["lensModel"])\n'
  '    return ET.tostring(root, encoding="utf-8", xml_declaration=True)\n'
  '\n'
  '\n'
  'def prepare_metadata(item, executable="exiftool"):\n'
  '    if snapshot(item.path) != item.fingerprint:\n'
  '        raise ImportFailure("SOURCE CHANGED: " + item.relative)\n'
  '    tags = probe(item.path, executable)\n'
  '    if snapshot(item.path) != item.fingerprint:\n'
  '        raise ImportFailure("SOURCE CHANGED: " + item.relative)\n'
  '    if item.route == "probe":\n'
  '        identify_photo(item, tags)\n'
  '    else:\n'
  '        confirm_camera(tags, {k: v for k, v in item.expected.items() if k != "lensModel"})\n'
  '    if "lensModel" in item.expected:\n'
  '        higher = next((tags[k] for k in ("LensID", "LensType", "LensSpec") if tags.get(k) is '
  'not None), None)\n'
  '        if higher is not None and higher != item.expected["lensModel"]:\n'
  '            raise ImportFailure("NEEDS REVIEW: embedded LensID/LensType/LensSpec would mask the '
